const items = $input.all();

const now = new Date();
const debutMoisActuel = new Date(now.getFullYear(), now.getMonth(), 1);
const debutMoisPrecedent = new Date(now.getFullYear(), now.getMonth() - 1, 1);

const moisFr = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const nomMois = moisFr[debutMoisPrecedent.getMonth()];
const annee = debutMoisPrecedent.getFullYear();

const articles = items
  .map(i => i.json)
  .filter(a => {
    const d = new Date(a.isoDate || a.pubDate);
    return d >= debutMoisPrecedent && d < debutMoisActuel;
  })
  .sort((a, b) => new Date(b.isoDate || b.pubDate) - new Date(a.isoDate || a.pubDate));

let html = `<h1>📰 Récapitulatif ${nomMois} ${annee}</h1>`;
html += `<p>${articles.length} article(s) publié(s) le mois dernier :</p><hr>`;

if (articles.length === 0) {
  html += `<p>Aucun article publié en ${nomMois}.</p>`;
} else {
  for (const a of articles) {
    const resume = (a.contentSnippet || a.content || '').replace(/<[^>]+>/g, '').trim().slice(0, 300);
    const date = new Date(a.isoDate || a.pubDate).toLocaleDateString('fr-FR');
    html += `<div style="margin-bottom:20px;">`;
    html += `<h3><a href="${a.link}">${a.title}</a></h3>`;
    html += `<p style="color:#555;">${resume}</p>`;
    html += `<p style="color:#999;font-size:12px;">${date}</p>`;
    html += `</div>`;
  }
}

return [{ json: {
  subject: `📰 Récapitulatif ${nomMois} ${annee} — ${articles.length} article(s)`,
  html: html,
  count: articles.length
} }];
